<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
/** Provides expense claim behavior within the WorkIntel application. */ class ExpenseClaim extends Model{protected $fillable=['uuid','workspace_id','member_id','project_id','cost_center_id','expense_policy_id','claim_number','title','status','currency','total_amount','approved_amount','reimbursement_status','submitted_at','reviewed_by','reviewed_at','reimbursed_at','payroll_run_id','note'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['total_amount'=>'decimal:2','approved_amount'=>'decimal:2','submitted_at'=>'datetime','reviewed_at'=>'datetime','reimbursed_at'=>'datetime'];}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}/** Handles the items operation for the current WorkIntel workflow. */ public function items():HasMany{return $this->hasMany(ExpenseClaimItem::class);}/** Handles the project operation for the current WorkIntel workflow. */ public function project():BelongsTo{return $this->belongsTo(Project::class);}/** Handles the policy operation for the current WorkIntel workflow. */ public function policy():BelongsTo{return $this->belongsTo(ExpensePolicy::class,'expense_policy_id');}/** Handles the reimbursement operation for the current WorkIntel workflow. */ public function reimbursement():HasMany{return $this->hasMany(ExpenseReimbursement::class);}}
